// Generated by esquadro: do not edit. Where the page shown is, for the
// header's breadcrumb: Home, a resource, one of its records, editing it.
import { useRouterState } from "@tanstack/react-router"
import { menu, isGroup } from "@/menu.ts"
import type { MenuItem } from "@/menu.ts"
import { base } from "../config.ts"
import { resources } from "../resources.gen.ts"
import { t } from "./i18n.ts"
import type { ResourceMeta } from "./meta.ts"

export interface Crumb {
  label: string
  to?: string
}

/** The pages of the menu, with their groups' pages. */
function pages(): MenuItem[] {
  return menu.main.flatMap((e) => (isGroup(e) ? e.items : [e]))
}

export function crumbsOf(pathname: string): Crumb[] {
  const root = base.replace(/\/$/, "")
  const path = root && pathname.startsWith(root) ? pathname.slice(root.length) : pathname
  const parts = path.split("/").filter(Boolean)
  const out: Crumb[] = [{ label: t("home"), to: "/" }]
  if (parts.length === 0) return out
  const meta = Object.values(resources as unknown as Record<string, ResourceMeta>).find((r) => r.name === parts[0])
  const page = pages().find((p) => p.to === `/${parts[0]}`)
  out.push({ label: meta?.label ?? page?.label ?? parts[0], to: `/${parts[0]}` })
  if (parts[1] === "new") out.push({ label: t("new") })
  else if (parts[1]) {
    out.push({ label: meta?.singular ?? parts[1], to: `/${parts[0]}/${parts[1]}` })
    if (parts[2] === "edit") out.push({ label: t("edit") })
  }
  return out
}

/** The breadcrumb of the page shown. */
export function useCrumbs(): Crumb[] {
  const pathname: string = useRouterState({ select: (s) => s.location.pathname })
  return crumbsOf(pathname)
}
